summary.update(typecheckPassed=True,diffWhitespaceCheckPassed=True,temporaryRouteRemoved=True,browserClosed=True,qaServerStopped=True)
(p/'final-results.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2))
fixes=[
 ('Заголовок демо на 320 px','Слово «регистрации» выходило за ширину заголовка внутри карточки. На самом узком экране кегль уменьшен; от 360 px сохранён прежний размер.', [('До','guest_demo-320.png')], [('После','guest_demo-320.png')]),
 ('Действия рецепта на 640 px','Группа действий расширяла документ на 57 px. До 768 px второстепенные действия доступны через меню; группы кнопок могут переноситься.', [], [('После · 640 px','recipe-toolbar-fixed-640.png')]),
 ('Статус управления пивоварней','Длинный статус сжимался в пять строк, значок почти исчезал. Текст, значок и кнопка теперь распределяются по строкам без сжатия кнопки.', [('До · 320 px','lease-before-320.png')], [('После · 320 px','lease-after-320.png')]),
 ('Выбор способа указания цены','«За всё количество» не помещалось в кнопку на 320–360 px. На узком экране переключатель занимает отдельную строку.', [], [('После · 320 px','price-fixed-focus-320.png')]),
 ('Описание на этикетке при 300 dpi','В «Крафте» округление размеров оставляло некоторым описаниям на два пикселя меньше нужной высоты. Добавлен подбор кегля в пределах 2–2,5 мм перед сокращением текста.', [], [('После · тестовая этикетка 300 dpi','label-craft-300dpi.png')]),
 ('Поля этикетки при увеличении текста','При размере текста 200% подписи крепости и горечи сталкивались. Число колонок теперь зависит от доступной ширины полей.', [], [('После · текст 200%','label-fields-text200-fixed.png')])
]
# The first pass preserved the original screenshot separately only for the lease;
# use the final demo screenshot without labelling an overwritten image as “before”.
fixes[0]=(fixes[0][0],fixes[0][1],[],fixes[0][3])
cards=[]
for i,(title,body,before,after) in enumerate(fixes,1):
 figures=''.join(f'<figure><a href="screens/{html.escape(file)}" target="_blank"><img src="screens/{html.escape(file)}" alt="{html.escape(label)}: {html.escape(title)}" loading="lazy"></a><figcaption>{html.escape(label)}</figcaption></figure>' for label,file in before+after)
 cards.append(f'<article><div class="number">{i:02}</div><h2>{html.escape(title)}</h2><p>{html.escape(body)}</p><div class="shots">{figures}</div></article>')
widths=', '.join(map(str,summary['widths']))
page='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NB · Проверка вёрстки после редактуры</title><style>
:root{font-family:system-ui,-apple-system,"Segoe UI",sans-serif;color:#1d2722;background:#f4f5f2;font-size:16px}*{box-sizing:border-box}body{margin:0}main{max-width:1200px;margin:auto;padding:48px 24px 72px}h1{max-width:850px;font-size:clamp(30px,4vw,48px);letter-spacing:-.035em;line-height:1.1;margin:14px 0 22px}h2{font-size:21px;line-height:1.3;margin:12px 0}p{line-height:1.6;color:#536057}.eyebrow{font-size:13px;text-transform:uppercase;letter-spacing:.12em}.pill{display:inline-block;color:#176342;background:#dff1e5;border-radius:20px;padding:7px 13px;font-size:13px;font-weight:600}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin:28px 0}.stat{padding:22px;background:white;border:1px solid #dce1d9;border-radius:16px}.stat strong{display:block;font-size:32px}.stat span{display:block;margin-top:6px;color:#536057;font-size:14px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,440px),1fr));gap:20px}article{min-width:0;background:white;border:1px solid #dce1d9;border-radius:18px;padding:24px;overflow:hidden}.number{color:#20825a;font-size:13px;font-weight:700}.shots{display:flex;gap:12px;align-items:flex-start}figure{margin:12px 0 0;min-width:0;flex:1}img{display:block;max-width:100%;max-height:520px;object-fit:contain;object-position:top;border-radius:9px;border:1px solid #e4e7e1;margin:auto}figcaption{font-size:12px;color:#657267;margin-top:8px;text-align:center}.details{margin:28px 0;padding:24px;background:#e9eee6;border-radius:16px}.details p{margin:8px 0}a{color:#14603f}li{margin:7px 0;line-height:1.5}details{margin-top:24px;padding:20px;border:1px solid #dce1d9;border-radius:16px}summary{cursor:pointer;font-weight:600}code{overflow-wrap:anywhere;font-size:13px}footer{font-size:13px;color:#657267;margin-top:24px}@media(max-width:480px){main{padding:28px 16px 48px}article{padding:18px}.shots{flex-wrap:wrap}figure{flex-basis:120px}}
</style><main><div class="eyebrow">NB · 23–24 октября 2026</div><h1>Проверка вёрстки после редактуры</h1><span class="pill">6 проблем исправлено</span><p>Проверены переносы длинных подписей, границы кнопок и полей, наложения и горизонтальное переполнение. Геометрические проверки дополнены просмотром снимков.</p><div class="stats"><div class="stat"><strong>69</strong><span>страниц приложения</span></div><div class="stat"><strong>14</strong><span>ширин от 320 до 1920 px</span></div><div class="stat"><strong>50</strong><span>браузерных сценариев прошли</span></div><div class="stat"><strong>116</strong><span>проверок кода и рендера прошли</span></div></div><div class="details"><p><b>Ширины:</b> WIDTHS CSS-пикселей.</p><p><b>Дополнительно:</b> альбомная ориентация 844×390 и 1024×600, размер текста 200%, светлая и тёмная темы, оформление «Хмель».</p><p><b>Движки:</b> основной обзор — Chromium. Ключевые сценарии повторены в Chromium и WebKit: телефоны, планшеты, настольные экраны. После последней правки сетки этикеток ещё 2 сценария прошли в обоих движках.</p></div><div class="grid">CARDS</div><details><summary>Что вошло в проверку</summary><ul><li>Главная, демо, BrewForge, каталог и карточки ингредиентов, справочник стилей, статьи, маркет, страницы пива по QR.</li><li>Склад: каталог, свой ингредиент, количество, цена и даты. Покупки: ручное добавление.</li><li>Рецепты: заполненные редакторы, публикация и меню действий, вода, импорт BeerXML/Brewfather, длинная ошибка импорта, диалог варки.</li><li>Все 17 калькуляторов, дополнительные режимы затирания и рефрактометра, настройка поправочного коэффициента.</li><li>Партии и журнал замеров. Приборы, настройки, подключение RAPT, полноэкранный пульт, состояния передачи управления, подтверждения нового адреса и удаления подключения, диалог диапазона температуры.</li><li>Этикетки: 5 форматов в браузере, оба шаблона, описания стилей на больших этикетках обеих ориентаций при 203/300 dpi.</li><li>Администрирование: каталог, редактор ингредиента, модерация, статьи, витрины, обратная связь, push-подписки, рецепты, приборы и прошивки.</li></ul><p>У редких состояний приборов проверялись настоящие компоненты с тестовыми данными и неактивными обработчиками. Команды проверялись только в локальном симуляторе.</p><p>В итоговых замерах не осталось обнаруженного переполнения страницы, обрезанных изменённых подписей и пересечений кнопок. TypeScript и проверка пробелов в diff прошли.</p></details><details><summary>Границы проверки и данные</summary><p>Это браузерная эмуляция. На физических iPhone/iPad и принтере этот прогон не выполнялся. Размер текста 200% проверялся при ширине 1280 px на складе, в редакторе рецепта и в редакторе этикетки.</p><p>Нативные push-уведомления и метаданные страниц не имеют собственной вёрстки внутри приложения. Длинное уведомление приложения проверено отдельно.</p><p>Диалоги с изменением данных открывались и отменялись. Нажатие «Сохранить» в тестовом диалоге температуры было отклонено автоматической проверкой как возможная мутация; для проверки вёрстки использованы открытие и отмена.</p><p>Часть начального прогона прервалась при переводе файловой системы WSL в режим только для чтения. После восстановления среды проверки возобновлены; исторические сбои тестовой обвязки сохранены в исходных логах и закрыты повторными проверками.</p><ul><li><a href="final-results.json">Итоговые результаты</a></li><li><a href="states.json">Замеры состояний и диалогов</a></li><li><a href="e2e.json">Браузерный прогон: 50 прошли, 6 пропущены по условию размера/проекта</a></li><li><a href="unit-tests.log">Тесты кода и печати</a></li><li><a href="layout-fixes.patch">Точечные изменения этого этапа</a></li></ul></details><footer>Согласованные формулировки сохранены. Временный тестовый экран удалён, тестовый браузер и отдельный сервер проверки остановлены.</footer></main></html>'''
(p/'report.html').write_text(page.replace('WIDTHS',widths).replace('CARDS',''.join(cards)))
(p/'report.md').write_text('''# Проверка вёрстки после редактуры NB

23–24 октября 2026. [Открыть отчёт со снимками](report.html).

Проверено 69 страниц, 14 ширин от 320 до 1920 CSS px и дополнительные состояния форм/диалогов. После исключения исторических замеров до исправления — 1316 успешных замеров без найденных переполнений, обрезанных изменённых подписей и пересечений кнопок.

Исправлено 6 проблем: заголовок демо на 320 px; панель действий рецепта на 640 px; длинный статус управления; переключатель способа указания цены; исчезновение описаний этикеток при 300 dpi; столкновение подписей этикетки при размере текста 200%.

50 браузерных сценариев прошли, 6 пропущены по явному условию проекта. После финального изменения сетки этикеток повторно прошли 2 сценария в Chromium/WebKit. 116 тестов кода и рендера прошли. TypeScript и git diff --check прошли.

Браузерная эмуляция; физических iPhone/iPad и принтера в этом прогоне не было. Все ограничения, исходные замеры и снимки приведены в HTML-отчёте.
''')
